SELECT CASE WHEN sqft >= 12357 THEN 'LARGE' ELSE 'SMALL' END AS sqft_tier, DATE_TRUNC('QUARTER', opened_date) AS quarter_start, STDDEV_SAMP(sqft) AS sqft_stddev, PERCENTILE_APPROX(sqft, ARRAY(0.25, 0.5, 0.75)) AS sqft_quartiles, MAX(sqft) AS max_sqft, SORT_ARRAY(COLLECT_SET(city)) AS city_list, ROUND(AVG(sqft), 2) AS avg_sqft FROM stores GROUP BY CASE WHEN sqft >= 12357 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('QUARTER', opened_date) ORDER BY avg_sqft DESC NULLS LAST;
